use std::fs;
use std::path::Path;

fn main() {
    // tauri-build rejects declared resource globs that match no file. The
    // runtime, Node, and pnpm payloads are generated by the prepare scripts
    // and gitignored, so a fresh checkout gets a placeholder until they run.
    for directory in ["resources/runtime", "resources/node", "resources/pnpm"] {
        ensure_non_empty(Path::new(directory));
    }
    tauri_build::build()
}

fn ensure_non_empty(directory: &Path) {
    let empty = fs::read_dir(directory)
        .map(|mut entries| entries.next().is_none())
        .unwrap_or(true);
    if !empty {
        return;
    }
    if let Err(error) = fs::create_dir_all(directory) {
        panic!("cannot create {}: {error}", directory.display());
    }
    if let Err(error) = fs::write(directory.join(".placeholder"), []) {
        panic!("cannot write {}: {error}", directory.join(".placeholder").display());
    }
}
